  <script>
    // Simple interactive calendar generator with Saturday start
    const calendarGrid = document.getElementById('calendar-grid');
    const confirmBtn = document.getElementById('confirm-btn');
    let selectedDate = null;
    let selectedTime = null;

    // Generate days for March 2025 (Saturday start)
    // March 1, 2025 is Saturday. Total 31 days.
    function renderCalendar() {
      calendarGrid.innerHTML = '';

      // March 2025 starts on Saturday (Day index 0 in Sat-start week)
      // Empty padding if needed (0 for Saturday)
      const paddingDays = 0; 
      const totalDays = 31;
      const today = 15; // Marked today

      for (let i = 0; i < paddingDays; i++) {
        const emptyDiv = document.createElement('div');
        calendarGrid.appendChild(emptyDiv);
      }

      for (let day = 1; day <= totalDays; day++) {
        const btn = document.createElement('button');
        btn.className = `h-10 w-10 mx-auto rounded-xl text-sm font-medium flex items-center justify-center transition-all relative ${
          day === today ? 'border-2 border-emerald-500 text-emerald-700 font-bold' : 'text-slate-700 hover:bg-slate-100'
        }`;
        btn.textContent = day;
        btn.dataset.day = day;

        btn.addEventListener('click', () => {
          document.querySelectorAll('#calendar-grid button').forEach(b => {
            b.classList.remove('bg-emerald-600', 'text-white', 'shadow-md', 'shadow-emerald-600/30');
            if(parseInt(b.dataset.day) === today && !b.classList.contains('selected')) {
              // keep today outline
            }
          });
          btn.classList.add('bg-emerald-600', 'text-white', 'shadow-md', 'shadow-emerald-600/30');
          selectedDate = day;
          checkSelection();
        });

        calendarGrid.appendChild(btn);
      }
    }

    // Time slot selection
    const timeSlots = document.querySelectorAll('.time-slot');
    timeSlots.forEach(slot => {
      slot.addEventListener('click', () => {
        timeSlots.forEach(s => s.classList.remove('border-emerald-600', 'bg-emerald-50', 'text-emerald-700', 'font-bold'));
        slot.classList.add('border-emerald-600', 'bg-emerald-50', 'text-emerald-700', 'font-bold');
        selectedTime = slot.dataset.time;
        checkSelection();
      });
    });

    function checkSelection() {
      if (selectedDate && selectedTime) {
        confirmBtn.removeAttribute('disabled');
        confirmBtn.classList.remove('opacity-50', 'cursor-not-allowed');
      }
    }

    confirmBtn.addEventListener('click', () => {
      if (selectedDate && selectedTime) {
        alert(`تم حجز الموعد بنجاح ليوم ${selectedDate} مارس 2025 الساعة ${selectedTime}`);
      }
    });

    renderCalendar();
  </script>
